///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.digitalChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.digitalChangePage = async function (tab) {
    /* sdd-asis-lifecycle:begin fn_DigitalChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.digitalListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_DigitalChangePageReq').get('lastSaveStatCd'));
    if (tab == 1) {
        $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsuTab');
    } else {
        if (tab == 2) {
            $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsurTab');
        } else {
            if (tab == 3) {
                return;
            } else {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_DigitalChangePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.lc.fn_isProcess('I')) {
        return;
    }
    scwin.form = (document.digitalListForm || { elements: [] });
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'saveSrtyLpTab');
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.digitalSub
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.digitalSub = async function () {
    /* sdd-asis-lifecycle:begin fn_DigitalSub — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.lc.fn_isProcess('S')) {
        return;
    }
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = "DigitalList.do";
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'submitList');
    await scwin.tx_fn_DigitalSub();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = "DigitalList.do";
    $c.util.getComponent('dma_DigitalChangePageReq').set('listBzTpCd', "");
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
